import{_ as a,o as t,c as n,a3 as o}from"./chunks/framework.DWfJTVRq.js";const u=JSON.parse(`{"title":"Electron","description":"The Node.js package runs in Electron's main process as it does in Node.js, with the same addon, since Node-API stays the same across Node.js and Electron…","frontmatter":{"title":"Electron","order":12,"languages":["node"],"prev":{"text":"Asynchronous API","link":"/guide/async"},"next":{"text":"How the engine is built","link":"/engine/architecture"}},"headers":[{"level":2,"title":"Where to open the database","slug":"where-to-open-the-database","link":"#where-to-open-the-database","children":[]},{"level":2,"title":"Several instances of the app","slug":"several-instances-of-the-app","link":"#several-instances-of-the-app","children":[]},{"level":2,"title":"Packaging","slug":"packaging","link":"#packaging","children":[]}],"relativePath":"guide/electron.md","filePath":"en/guide/electron.md","lastUpdated":1791000973000}`),s={name:"guide/electron.md"};function i(r,e,c,h,l,d){return t(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="electron" tabindex="-1">Electron <a class="header-anchor" href="#electron" aria-label="Permalink to &quot;Electron&quot;">​</a></h1><p>The Node.js package runs in Electron&#39;s main process as it does in Node.js, with the same addon, since Node-API stays the same across Node.js and Electron versions.</p><h2 id="where-to-open-the-database" tabindex="-1">Where to open the database <a class="header-anchor" href="#where-to-open-the-database" aria-label="Permalink to &quot;Where to open the database&quot;">​</a></h2><p>Open the database in the main process, or in a utility process of your own (<code>utilityProcess</code>), and give the renderers what they need through IPC. A renderer is sandboxed by default and cannot load a native addon. The package&#39;s tests run it in Electron 44.</p><h2 id="several-instances-of-the-app" tabindex="-1">Several instances of the app <a class="header-anchor" href="#several-instances-of-the-app" aria-label="Permalink to &quot;Several instances of the app&quot;">​</a></h2><p>Several processes can have the file open at once, two instances of the app included. Each opens it with a handle of its own, and the engine coordinates them through the operating system&#39;s file locks: one writes at a time, and a writer that waits longer than the busy timeout fails with <code>BUSY</code>. Within one process, opening the file again gives another handle to the same database. <a href="./processes">Several processes</a> has the rules that come with the locks.</p><h2 id="packaging" tabindex="-1">Packaging <a class="header-anchor" href="#packaging" aria-label="Permalink to &quot;Packaging&quot;">​</a></h2><p>A packaged app should keep the addon outside the <code>asar</code> archive, from which Electron can load a native addon only by copying it out first. electron-builder leaves it outside by itself, and Electron Forge does with its auto-unpack-natives plugin.</p>',8)])])}const g=a(s,[["render",i]]);export{u as __pageData,g as default};
